        {Theme::Light, Property("font-size", "16px")},
        {Theme::Dark, Property("background-color", "#333")}
    };

    // Add properties for each theme
    for (const auto& [theme, property] : themesProperties) {
        manager.addProperty(theme, property);
    }

    // Verify that properties are added correctly for each theme
    for (const auto& [theme, property] : themesProperties) {
        EXPECT_EQ(manager.getProperty(theme), property);
    }
}
